import re
from taf.hw.rf_attenuator.exceptions import AttenuatorCmdError
from taf.hw.rf_attenuator.devices.topyoung.topyoung import TopYoung


class TopYoungTAS32B3207G849005SDES(TopYoung):

    _READ_CMD = 'READm:STATus:{}'
    _READ_RES_OK = r'READm:STATus:{},(\d+)'
    _READ_RES_FAIL = 'READm:STATus:FAIL'

    _SET_CMD = 'SETM:ATT:{},{}'
    _SET_RES_OK = 'SETM:ATT:OK'
    _SET_RES_FAIL = 'SETM:ATT:FAIL'

    _ALLOCK_B_PORTS = "SET:ALLOC:CHANnel:{}"
    _ALLOCK_B_PORTS_OK = "SET:ALLOC:CHANnel:OK"
    _ALLOCK_B_PORTS_FAIL = "SET:ALLOC:CHANnel:FAIL"

    _B_PORT_NUMBER = 32

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        for index in range(len(rf_port_addresses)):
            port, value = rf_port_addresses[index], attenuation_values_db[index]
            self._set_single_port_decibel_attenuation(port, value)

    def _is_channel_valid(self, rf_port_address):
        """
        rf_port_address value should be A1B2, A12B10 like format.
        """
        pattern = r'^A\d+B\d+$'
        if not re.match(pattern, rf_port_address):
            msg = 'Channel invalid, {} not in format A1B1 to A24B32'.format(rf_port_address)
            raise AttenuatorCmdError(msg)

    def connect(self, **kwargs):
        super(TopYoungTAS32B3207G849005SDES, self).connect(**kwargs)
        self.alloc_b_ports()

    def alloc_b_ports(self):
        ports = [str(no) for no in range(1, self._B_PORT_NUMBER + 1)]
        result = self._write_and_read(self._ALLOCK_B_PORTS.format(";".join(ports)))
        if self._ALLOCK_B_PORTS_FAIL in result:
            raise AttenuatorCmdError('Allocating ports {} failed.'.format(ports))
